settings.custom_liquid:
{%- assign is_arabic = false -%}
{%- if request.locale.iso_code contains 'ar' -%}
  {%- assign is_arabic = true -%}
{%- endif -%}

<style>
  .ww-features{
    list-style: none;
    padding: 0;
    margin: 18px 0 20px;
    width: 100%;
  }

  .ww-features li{
    display: flex;
    align-items: flex-start;
    gap: 12px;
    width: 100%;
    padding: 6px 0;
    font-size: 16px;
    line-height: 1.5;
    color: #2d2d2d;
    font-family: inherit;
    text-align: left;
  }

  .ww-features--rtl{
    direction: rtl;
  }

  .ww-features--rtl li{
    text-align: right;
    direction: rtl;
  }

  .ww-features li:not(:last-child){
    border-bottom: 0px solid #eef2f5;
  }

  .ww-features img{
    width: 18px;
    height: 18px;
    margin-top: 3px;
    flex-shrink: 0;
  }
</style>

<ul class="ww-features {% if is_arabic %}ww-features--rtl{% endif %}">
  <li>
    <img src="https://cdn.shopify.com/s/files/1/0847/2120/5545/files/check.png?v=1765462752" alt="">
    {% if is_arabic %}
      ٣٤ صوت هادئ، من الوايت نويز للتهويدات وأصوات الطبيعة
    {% else %}
      34 soothing sounds including white noise, lullabies & nature sounds
    {% endif %}
  </li>

  <li>
    <img src="https://cdn.shopify.com/s/files/1/0847/2120/5545/files/check.png?v=1765462752" alt="">
    {% if is_arabic %}
      ضو ليلي ناعم بـ ٧ ألوان مريحة
    {% else %}
      Soft night light with 7 calming colors
    {% endif %}
  </li>

  <li>
    <img src="https://cdn.shopify.com/s/files/1/0847/2120/5545/files/check.png?v=1765462752" alt="">
    {% if is_arabic %}
      تحكّم بالصوت، العلو، والضو من خلال التطبيق
    {% else %}
      App control for sound, volume & light
    {% endif %}
  </li>

  <li>
    <img src="https://cdn.shopify.com/s/files/1/0847/2120/5545/files/check.png?v=1765462752" alt="">
    {% if is_arabic %}
      روتين نوم مخصّص مع مؤقّت تلقائي
    {% else %}
      Custom sleep routines with auto timer
    {% endif %}
  </li>

  <li>
    <img src="https://cdn.shopify.com/s/files/1/0847/2120/5545/files/check.png?v=1765462752" alt="">
    {% if is_arabic %}
      بيساعد البيبي ينام أسرع ويضل نايم لمدة أطول
    {% else %}
      Helps babies fall asleep faster & stay asleep longer
    {% endif %}
  </li>
</ul>

{%- assign is_arabic = false -%}
{%- if request.locale.iso_code contains 'ar' -%}
  {%- assign is_arabic = true -%}
{%- endif -%}

<style>
/* SECTION */
.why-noise-section {
  width: 100%;
  padding: 70px 20px;
  box-sizing: border-box;
  content-visibility: auto;
  contain-intrinsic-size: 720px;
}

/* INNER */
.why-noise-inner {
  width: 100%;
  max-width: 1300px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  gap: 60px;
  contain: layout paint;
}

/* RTL */
.why-noise-section--rtl {
  direction: rtl;
}

.why-noise-section--rtl .why-noise-content {
  text-align: right;
}

/* IMAGE WRAPPER — FORCE SQUARE */
.why-noise-image {
  flex: 0 0 auto;
  width: 620px;
  aspect-ratio: 1 / 1;
  border-radius: 20px;
  overflow: hidden;
}

/* IMAGE */
.why-noise-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* CONTENT */
.why-noise-content {
  flex: 1;
}

.why-noise-content h2 {
  font-size: 34px;
  margin: 0 0 14px;
  font-weight: 800;
}

.why-noise-content h2 span {
  color: #7AC8F0;
}

.why-noise-content p {
  font-size: 20px;
  line-height: 1.45;
  margin-bottom: 28px;
}

.why-noise-content p span {
  color: #7AC8F0;
  font-weight: 600;
}

/* LIST */
.why-noise-list {
  list-style: none;
  padding: 0;
  margin: 0 0 36px;
}

.why-noise-list li {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 17px;
  margin-bottom: 18px;
}

.why-noise-section--rtl .why-noise-content {
  text-align: right;
}

.why-noise-section--rtl .why-noise-list {
  padding: 0;
  margin-right: 0;
  margin-left: 0;
}

.why-noise-section--rtl .why-noise-list li {
  direction: rtl;
  flex-direction: row;
  justify-content: flex-start;
  text-align: right;
}

.why-noise-list img {
  width: 28px;
  height: 28px;
  flex-shrink: 0;
}

/* BUTTON */
.why-noise-btn {
  display: inline-block;
  padding: 16px 48px;
  background: #7AC8F0;
  color: #fff;
  border-radius: 999px;
  text-decoration: none;
  font-size: 17px;
  font-weight: 600;
  transition: opacity 0.2s ease;
}

.why-noise-btn:hover {
  opacity: 0.85;
}

/* MOBILE — STILL SQUARE */
@media (max-width: 768px) {
  .why-noise-inner {
    flex-direction: column;
    gap: 32px;
  }

  .why-noise-image {
    width: 100%;
    max-width: 360px;
    aspect-ratio: 1 / 1;
  }

  .why-noise-content h2 {
    font-size: 26px;
  }

  .why-noise-content p {
    font-size: 17px;
  }

  .why-noise-list li {
    font-size: 15.5px;
  }

  .why-noise-btn {
    width: 100%;
    text-align: center;
  }
}
</style>

<section class="why-noise-section {% if is_arabic %}why-noise-section--rtl{% endif %}">
  <div class="why-noise-inner">

    <!-- IMAGE -->
    <div class="why-noise-image">
      <img 
        src="https://cdn.shopify.com/s/files/1/0847/2120/5545/files/WhatsAppVideo2025-12-26at14.01.34-ezgif.com-optimize.gif?v=1766757431"
        alt="{% if is_arabic %}جهاز الأصوات الهادئة من WeeWonders{% else %}WeeWonders Noise Machine{% endif %}"
        loading="lazy"
      >
    </div>

    <!-- CONTENT -->
    <div class="why-noise-content">
      <h2>
        {% if is_arabic %}
          ليش <span>جهاز الأصوات من WeeWonders؟</span>
        {% else %}
          WHY OUR <span>NOISE MACHINE?</span>
        {% endif %}
      </h2>

      <p>
        {% if is_arabic %}
          ودّعي <span>ليالي السهر</span>، وخلّي وقت النوم أهدى وأسهل لطفلك.
        {% else %}
          Say goodbye to <span>sleepless nights</span>, and hello to
          <span>peaceful dreams.</span>
        {% endif %}
      </p>

      <ul class="why-noise-list">
        <li>
          <img src="https://cdn.shopify.com/s/files/1/0847/2120/5545/files/check.png?v=1765462752" alt="">
          {% if is_arabic %}
            ٣٤ صوت مريح لكل وقت ومزاج
          {% else %}
            34 Soothing Sounds for Every Moment
          {% endif %}
        </li>

        <li>
          <img src="https://cdn.shopify.com/s/files/1/0847/2120/5545/files/check.png?v=1765462752" alt="">
          {% if is_arabic %}
            بيساعد البيبي ينام أسرع ولمدة أطول
          {% else %}
            Helps babies sleep faster, longer
          {% endif %}
        </li>

        <li>
          <img src="https://cdn.shopify.com/s/files/1/0847/2120/5545/files/check.png?v=1765462752" alt="">
          {% if is_arabic %}
            تحكّم ذكي من خلال التطبيق
          {% else %}
            Smart app remote control
          {% endif %}
        </li>
      </ul>

      <a href="#" class="why-noise-btn">
        {% if is_arabic %}
          تسوّقيه الآن
        {% else %}
          Shop Now
        {% endif %}
      </a>
    </div>

  </div>
</section>
